import os, pathlib, sys, yaml
home = pathlib.Path(os.environ.get("HERMES_HOME", pathlib.Path.home() / ".hermes")).expanduser()
config_path = home / "config.yaml"
try:
    config = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
except FileNotFoundError:
    sys.exit(f"FAIL: Hermes config missing: {config_path}")
except Exception as exc:
    sys.exit(f"FAIL: cannot read Hermes config {config_path}: {exc}")
enabled = config.get("plugins", {}).get("enabled", [])
disabled = config.get("plugins", {}).get("disabled", [])
plugin = "thesystem-memory-write-labels"
if not isinstance(enabled, list) or plugin not in enabled or (isinstance(disabled, list) and plugin in disabled):
    sys.exit(f"FAIL: {plugin} is not enabled in {config_path}")
import datetime, json, re, subprocess
state_path = home / "gateway_state.json"
try:
    state = json.loads(state_path.read_text(encoding="utf-8"))
    pid = int(state["pid"])
    if state.get("gateway_state") not in ("running", "degraded"):
        raise ValueError(f"gateway_state={state.get('gateway_state')!r}")
    os.kill(pid, 0)
except Exception as exc:
    sys.exit(f"FAIL: running gateway state unavailable: {exc}")
try:
    started_text = subprocess.run(["ps", "-p", str(pid), "-o", "lstart="], env={**os.environ, "LC_ALL": "C"}, check=True,
                                  capture_output=True, text=True).stdout.strip()
    started = datetime.datetime.strptime(started_text, "%a %b %d %H:%M:%S %Y").astimezone()
except Exception as exc:
    sys.exit(f"FAIL: cannot determine gateway pid {pid} start time: {exc}")
log = home / "logs" / "agent.log"
pattern = re.compile(r"^(\d{4}-\d\d-\d\d \d\d:\d\d:\d\d,\d+) .*Session plugin prompt section: .*plugin=thesystem-memory-write-labels ")
try:
    lines = log.read_text(encoding="utf-8", errors="replace").splitlines()
except FileNotFoundError:
    sys.exit(f"FAIL: Hermes agent log missing: {log}")
found = False
for line in lines:
    match = pattern.match(line)
    if match:
        try:
            logged = datetime.datetime.strptime(match.group(1), "%Y-%m-%d %H:%M:%S,%f").astimezone()
            if logged >= started:
                found = True
                break
        except ValueError:
            continue
if not found:
    sys.exit(f"FAIL: no plugin-loaded session log entry after gateway pid {pid} started at {started_text}")
print(f"OK: plugin enabled and logged loaded by gateway pid {pid} after {started_text}")
