import json, os, pathlib, sys
home = pathlib.Path(os.environ.get("HERMES_HOME", pathlib.Path.home() / ".hermes")).expanduser()
log = home / "curate-memory" / "write-labels.jsonl"
queue = home / "curate-memory" / "skill-requests.jsonl"
proposals = home / "curate-memory" / "control-proposals.jsonl"
try:
    rows = [json.loads(line) for line in log.read_text(encoding="utf-8").splitlines() if line.strip()]
except FileNotFoundError:
    print("OK: no routed memory writes")
    raise SystemExit(0)
except Exception as exc:
    sys.exit(f"FAIL: cannot parse routed-write log {log}: {exc}")
def read_rows(path):
    try:
        return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
    except FileNotFoundError:
        return []
    except Exception as exc:
        sys.exit(f"FAIL: cannot parse destination ledger {path}: {exc}")
skill_ids = {str(row.get("request_id")) for row in read_rows(queue) if row.get("request_id")}
proposal_ids = {str(row.get("id")) for row in read_rows(proposals) if row.get("id")}
orphans = []
for row in rows:
    if not isinstance(row, dict) or row.get("decision") != "routed":
        continue
    label, artifact, destination = row.get("label"), row.get("artifact"), row.get("destination")
    if label == "procedure":
        exists = str(artifact) in skill_ids
    elif label == "safety-rule":
        exists = str(artifact) in proposal_ids
    elif isinstance(label, str) and label.startswith("project-fact:"):
        exists = isinstance(artifact, str) and pathlib.Path(artifact).is_file()
    else:
        exists = isinstance(artifact, str) and pathlib.Path(artifact).is_file()
    if not exists:
        orphans.append(f"label={label!r} artifact={artifact!r} destination={destination!r}")
if orphans:
    sys.exit("FAIL: routed writes have missing artifacts: " + "; ".join(orphans))
print("OK: every routed write has its destination artifact")
