import datetime, json, os, pathlib, sys
home = pathlib.Path(os.environ.get("HERMES_HOME", pathlib.Path.home() / ".hermes")).expanduser()
path = home / "curate-memory" / "skill-requests.jsonl"
try:
    rows = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
except FileNotFoundError:
    print("OK: no procedure requests queued")
    raise SystemExit(0)
except Exception as exc:
    sys.exit(f"FAIL: cannot parse skill request queue {path}: {exc}")
latest = {}
for row in rows:
    if isinstance(row, dict) and row.get("request_id"):
        latest[row["request_id"]] = row
now = datetime.datetime.now().astimezone()
stuck = []
for request_id, row in latest.items():
    if row.get("status") not in ("queued", "running"):
        continue
    try:
        created = datetime.datetime.fromisoformat(row["created_at"])
        age = (now - created.astimezone()).total_seconds()
    except (KeyError, TypeError, ValueError):
        sys.exit(f"FAIL: queued request {request_id} has invalid created_at")
    if age > 3600:
        stuck.append(f"{request_id} status={row.get('status')} age={int(age)}s")
if stuck:
    sys.exit("FAIL: procedure requests stuck over 1 hour: " + "; ".join(stuck))
print(f"OK: no non-final procedure request older than 1 hour ({len(latest)} latest requests checked)")
