import datetime, json, os, pathlib, sys
from zoneinfo import ZoneInfo
home = pathlib.Path(os.environ.get("HERMES_HOME", pathlib.Path.home() / ".hermes")).expanduser()
path = home / "curate-memory" / "skill-requests.jsonl"
today = datetime.datetime.now(ZoneInfo("America/Bogota")).date()
try:
    rows = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
except FileNotFoundError:
    print(f"OK: 0 skill runs on {today.isoformat()} (cap 150)")
    raise SystemExit(0)
except Exception as exc:
    sys.exit(f"FAIL: cannot parse skill request queue {path}: {exc}")
runs = set()
for row in rows:
    if not isinstance(row, dict) or not row.get("run_id") or row.get("status") not in ("queued", "running", "done", "failed"):
        continue
    try:
        created = datetime.datetime.fromisoformat(row["created_at"]).astimezone(ZoneInfo("America/Bogota")).date()
    except (KeyError, TypeError, ValueError):
        continue
    if created == today:
        runs.add(row["run_id"])
if len(runs) > 150:
    sys.exit(f"FAIL: {len(runs)} skill runs on {today.isoformat()} exceed the 150/day cap")
print(f"OK: {len(runs)} skill runs on {today.isoformat()} (cap 150)")
